fn main() {
    let mut scene = blr::Scene::new();
    scene
        .add(
            blr::Object::cube("foundation", 3.4)
                .at([0.0, 0.0, 0.35])
                .scaled([1.0, 1.0, 0.2])
                .colored([0.22, 0.28, 0.38, 1.0]),
        )
        .expect("valid foundation");

    for floor in 0..7 {
        let height = 0.8 + floor as f64 * 0.72;
        let width = 2.7 - floor as f64 * 0.24;
        scene
            .add(
                blr::Object::cube(format!("tower floor {floor}"), 1.0)
                    .at([0.0, 0.0, height])
                    .scaled([width, width, 0.34])
                    .colored([
                        0.32 + floor as f64 * 0.045,
                        0.48 + floor as f64 * 0.025,
                        0.78 - floor as f64 * 0.055,
                        1.0,
                    ]),
            )
            .expect("valid tower floor");
    }

    scene
        .add(
            blr::Object::cone("roof", 1.05, 1.5)
                .at([0.0, 0.0, 6.7])
                .segments(8)
                .colored([0.92, 0.37, 0.12, 1.0]),
        )
        .expect("valid roof");
    scene.emit().expect("emit scene");
}

use std::f64::consts::TAU;

fn main() {
    let mut scene = blr::Scene::new();
    scene
        .add(
            blr::Object::sphere("central star", 0.92)
                .segments(24)
                .rings(12)
                .colored([1.0, 0.48, 0.08, 1.0]),
        )
        .expect("valid star");
    scene
        .add(
            blr::Object::torus("tilted orbit", 2.15, 0.07)
                .rotated([0.28, 0.16, 0.0])
                .major_segments(48)
                .minor_segments(10)
                .colored([0.16, 0.68, 0.88, 1.0]),
        )
        .expect("valid orbit");

    for moon in 0..8 {
        let angle = TAU * moon as f64 / 8.0;
        scene
            .add(
                blr::Object::sphere(format!("moon {moon}"), 0.2 + (moon % 3) as f64 * 0.045)
                    .at([2.15 * angle.cos(), 2.15 * angle.sin(), 0.0])
                    .segments(12)
                    .rings(8)
                    .colored([0.38, 0.78 - moon as f64 * 0.035, 0.42, 1.0]),
            )
            .expect("valid moon");
    }
    scene.emit().expect("emit scene");
}

fn main() {
    let mut scene = blr::Scene::new();
    let cells = 8;
    for x in 0..cells {
        for y in 0..cells {
            let fx = x as f64 / (cells - 1) as f64;
            let fy = y as f64 / (cells - 1) as f64;
            let wave = (fx * 9.0).sin() * (fy * 8.0).cos();
            let height = 0.34 + (wave + 1.0) * 0.44;
            let color = [
                0.13 + fx * 0.18,
                0.3 + fy * 0.42,
                0.19 + (wave + 1.0) * 0.12,
                1.0,
            ];
            scene
                .add(
                    blr::Object::cube(format!("tile {x}-{y}"), 1.0)
                        .at([x as f64 - 3.5, y as f64 - 3.5, height * 0.5])
                        .scaled([0.47, 0.47, height * 0.5])
                        .colored(color),
                )
                .expect("heightfield fits bridge limits");
        }
    }
    scene.emit().expect("emit scene");
}
